pub(crate) type BoxedResidentStream = Box<dyn ResidentStream>;

pub(crate) struct PendingRequest {
    pub(crate) stream: BoxedResidentStream,
    pub(crate) request_id: [u8; crate::FRAME_REQUEST_ID_BYTES],
    pub(crate) request_digest: [u8; crate::FRAME_DIGEST_BYTES],
    pub(crate) length: usize,
    pub(crate) payload_prefix: Vec<u8>,
    pub(crate) accepted_at: Instant,
}

pub(crate) fn constant_time_eq(left: &[u8], right: &[u8]) -> bool {
    if left.len() != right.len() {
        return false;
    }
    let mut difference = 0u8;
    for (left_byte, right_byte) in left.iter().zip(right) {
        difference |= left_byte ^ right_byte;
    }
    difference == 0
}

pub(crate) fn hmac_sha256(key: &[u8], label: &[u8], nonce: &[u8]) -> [u8; crate::AUTH_PROOF_BYTES] {
    const BLOCK_BYTES: usize = 64;
    let mut key_block = [0u8; BLOCK_BYTES];
    if key.len() > BLOCK_BYTES {
        let digest = Sha256::digest(key);
        key_block[..digest.len()].copy_from_slice(&digest);
    } else {
        key_block[..key.len()].copy_from_slice(key);
    }

    let mut inner_pad = [0x36u8; BLOCK_BYTES];
    let mut outer_pad = [0x5cu8; BLOCK_BYTES];
    for index in 0..BLOCK_BYTES {
        inner_pad[index] ^= key_block[index];
        outer_pad[index] ^= key_block[index];
    }

    let mut inner = Sha256::new();
    inner.update(inner_pad);
    inner.update(label);
    inner.update(nonce);
    let inner_digest = inner.finalize();

    let mut outer = Sha256::new();
    outer.update(outer_pad);
    outer.update(inner_digest);
    let digest = outer.finalize();
    let mut proof = [0u8; crate::AUTH_PROOF_BYTES];
    proof.copy_from_slice(&digest);
    proof
}

fn authenticate_resident_stream(
    stream: &mut dyn ResidentStream,
    token: &[u8; crate::AUTH_TOKEN_BYTES],
) -> Result<(), String> {
    stream
        .set_resident_read_timeout(Some(crate::AUTH_TIMEOUT))
        .map_err(|_| "native_resident_auth_timeout_failed".to_owned())?;
    stream
        .set_resident_write_timeout(Some(crate::AUTH_TIMEOUT))
        .map_err(|_| "native_resident_auth_timeout_failed".to_owned())?;
    let _ = stream.configure_low_latency();

    let mut nonce = [0u8; crate::AUTH_NONCE_BYTES];
    stream
        .read_exact(&mut nonce)
        .map_err(|_| "native_resident_auth_nonce_failed".to_owned())?;
    let server_proof = hmac_sha256(token, crate::SERVER_PROOF_LABEL, &nonce);
    stream
        .write_all(&server_proof)
        .map_err(|_| "native_resident_auth_proof_failed".to_owned())?;

    let mut client_proof = [0u8; crate::AUTH_PROOF_BYTES];
    stream
        .read_exact(&mut client_proof)
        .map_err(|_| "native_resident_auth_client_failed".to_owned())?;
    let expected = hmac_sha256(token, crate::CLIENT_PROOF_LABEL, &nonce);
    if !constant_time_eq(&client_proof, &expected) {
        return Err("native_resident_auth_rejected".into());
    }
    Ok(())
}

fn read_request_header(mut stream: BoxedResidentStream) -> Result<PendingRequest, String> {
    stream
        .set_resident_read_timeout(Some(crate::HEADER_TIMEOUT))
        .map_err(|_| "native_frame_timeout_failed".to_owned())?;
    let mut header = [0u8; crate::FRAME_HEADER_BYTES];
    stream
        .read_exact(&mut header)
        .map_err(|_| "native_frame_header_failed".to_owned())?;
    if !constant_time_eq(&header[..4], crate::REQUEST_MAGIC) {
        return Err("native_frame_version_mismatch".to_owned());
    }
    let mut request_id = [0u8; crate::FRAME_REQUEST_ID_BYTES];
    request_id.copy_from_slice(&header[4..4 + crate::FRAME_REQUEST_ID_BYTES]);
    let digest_start = 4 + crate::FRAME_REQUEST_ID_BYTES;
    let mut request_digest = [0u8; crate::FRAME_DIGEST_BYTES];
    request_digest.copy_from_slice(&header[digest_start..digest_start + crate::FRAME_DIGEST_BYTES]);
    let length = u32::from_be_bytes(
        header[crate::FRAME_HEADER_BYTES - 4..]
            .try_into()
            .map_err(|_| "native_frame_header_failed".to_owned())?,
    ) as usize;
    if length == 0 || length > crate::MAX_NATIVE_REQUEST_BYTES {
        return Err("native_request_too_large".to_owned());
    }
    Ok(PendingRequest {
        stream,
        request_id,
        request_digest,
        length,
        payload_prefix: Vec::new(),
        accepted_at: Instant::now(),
    })
}

fn write_bound_response(
    stream: &mut dyn ResidentStream,
    request_id: &[u8; crate::FRAME_REQUEST_ID_BYTES],
    response: &[u8],
) -> Result<(), String> {
    if response.is_empty() || response.len() > crate::MAX_NATIVE_RESPONSE_BYTES {
        return Err("native_response_too_large".to_owned());
    }
    stream
        .set_resident_write_timeout(Some(crate::RESPONSE_TIMEOUT))
        .map_err(|_| "native_frame_timeout_failed".to_owned())?;
    let digest = Sha256::digest(response);
    let mut header = Vec::with_capacity(crate::FRAME_HEADER_BYTES);
    header.extend_from_slice(crate::RESPONSE_MAGIC);
    header.extend_from_slice(request_id);
    header.extend_from_slice(&digest);
    header.extend_from_slice(&(response.len() as u32).to_be_bytes());
    stream
        .write_all(&header)
        .map_err(|error| crate::hardening::write_error(&error, "native_frame_write_failed"))?;
    stream
        .write_all(response)
        .map_err(|error| crate::hardening::write_error(&error, "native_frame_write_failed"))?;
    stream
        .flush()
        .map_err(|error| crate::hardening::write_error(&error, "native_frame_write_failed"))?;
    Ok(())
}

fn write_overload(pending: &mut PendingRequest) {
    let response = crate::resident_protocol::error_response("native_overloaded", true);
    let _ = write_bound_response(&mut *pending.stream, &pending.request_id, &response);
}

fn handle_pending_request(
    mut pending: PendingRequest,
    policy_store: Option<&crate::policy_store::PolicySnapshotStore>,
) {
    if crate::hardening::request_expired(pending.accepted_at) {
        let response =
            crate::resident_protocol::error_response("native_request_deadline_exceeded", true);
        let _ = write_bound_response(&mut *pending.stream, &pending.request_id, &response);
        return;
    }
    let _ = pending
        .stream
        .set_resident_read_timeout(Some(crate::PAYLOAD_TIMEOUT));
    let prefix_length = pending.payload_prefix.len();
    let mut request = vec![0u8; pending.length];
    request[..prefix_length].copy_from_slice(&pending.payload_prefix);
    let mut disposition = crate::resident_protocol::LifecycleDisposition::Continue;
    let response = if pending
        .stream
        .read_exact(&mut request[prefix_length..])
        .is_err()
    {
        crate::resident_protocol::error_response("native_frame_read_failed", false)
    } else {
        let digest = Sha256::digest(&request);
        if !constant_time_eq(&digest, &pending.request_digest) {
            crate::resident_protocol::error_response("native_request_digest_mismatch", false)
        } else {
            match catch_unwind(AssertUnwindSafe(|| {
                crate::observe_native_phase!(
                    ResidentEvaluate,
                    crate::resident_protocol::evaluate_resident_bytes_started(
                        &request,
                        policy_store,
                        pending.accepted_at,
                    )
                )
            })) {
                Ok(Ok(evaluation)) => {
                    disposition = evaluation.disposition;
                    evaluation.response
                }
                Ok(Err(reason)) => crate::resident_protocol::safe_error_response(&reason, false),
                Err(_panic) => {
                    crate::resident_protocol::error_response("native_runtime_panicked", false)
                }
            }
        }
    };
    if disposition == crate::resident_protocol::LifecycleDisposition::Shutdown {
        crate::managed_resident::request_shutdown();
    }
    let _ = write_bound_response(&mut *pending.stream, &pending.request_id, &response);
    if disposition == crate::resident_protocol::LifecycleDisposition::Shutdown {
        crate::managed_resident::shutdown_response_sent();
    }
}

fn spawn_workers<T, F>(count: usize, receiver: Receiver<T>, handler: F)
where
    T: Send + 'static,
    F: Fn(T) + Send + Sync + 'static,
{
    let receiver = Arc::new(Mutex::new(receiver));
    let handler = Arc::new(handler);
    for _ in 0..count {
        let receiver = Arc::clone(&receiver);
        let handler = Arc::clone(&handler);
        thread::spawn(move || loop {
            let next = match receiver.lock() {
                Ok(guard) => guard.recv(),
                Err(_) => return,
            };
            match next {
                Ok(item) => handler(item),
                Err(_) => return,
            }
        });
    }
}

pub(crate) fn start_resident_workers(
    token: Arc<[u8; crate::AUTH_TOKEN_BYTES]>,
    policy_store: Option<Arc<crate::policy_store::PolicySnapshotStore>>,
) -> SyncSender<BoxedResidentStream> {
    let (evaluation_sender, evaluation_receiver) =
        sync_channel::<PendingRequest>(crate::EVALUATION_QUEUE_CAPACITY);
    let evaluation_policy_store = policy_store.clone();
    spawn_workers(
        crate::EVALUATION_WORKERS,
        evaluation_receiver,
        move |pending| {
            handle_pending_request(pending, evaluation_policy_store.as_deref());
        },
    );

    let (authentication_sender, authentication_receiver) =
        sync_channel::<BoxedResidentStream>(crate::AUTH_QUEUE_CAPACITY);
    spawn_workers(
        crate::AUTH_WORKERS,
        authentication_receiver,
        move |mut stream| {
            if authenticate_resident_stream(&mut *stream, &token).is_err() {
                return;
            }
            let mut pending = match read_request_header(stream) {
                Ok(value) => value,
                Err(_) => return,
            };
            pending
                .payload_prefix
                .resize(pending.length.min(crate::AUTHENTICATED_PREFETCH_BYTES), 0);
            let available = match pending
                .stream
                .try_read_available(&mut pending.payload_prefix)
            {
                Ok(value) => value,
                Err(_) => return,
            };
            pending.payload_prefix.truncate(available);
            if available == pending.length {
                handle_pending_request(pending, policy_store.as_deref());
                return;
            }
            match evaluation_sender.try_send(pending) {
                Ok(()) => {}
                Err(TrySendError::Full(returned)) => {
                    let mut pending = returned;
                    write_overload(&mut pending);
                }
                Err(TrySendError::Disconnected(_returned)) => {}
            }
        },
    );
    authentication_sender
}

pub(crate) fn admit_connection(
    sender: &SyncSender<BoxedResidentStream>,
    stream: BoxedResidentStream,
) -> Result<(), String> {
    match sender.try_send(stream) {
        Ok(()) => Ok(()),
        Err(TrySendError::Full(_stream)) => Ok(()),
        Err(TrySendError::Disconnected(_stream)) => {
            Err("native_resident_worker_pool_stopped".to_owned())
        }
    }
}

//! Aggregate-only native phase observations for an explicitly diagnostic build.
//!
//! The default macro expands to its original expression. No request data or
//! free-form errors enter this module. These inclusive spans are not additive,
//! and instrumented timings are never eligible for headline SLO measurements.

#[cfg(not(all(feature = "diagnostic-phases", target_os = "linux")))]
#[macro_export]
macro_rules! observe_native_phase {
    ($phase:ident, $operation:expr) => {
        $operation
    };
}

#[cfg(all(feature = "diagnostic-phases", target_os = "linux"))]
#[macro_export]
macro_rules! observe_native_phase {
    ($phase:ident, $operation:expr) => {{
        let observation = $crate::native_phase_observation::begin(
            $crate::native_phase_observation::Phase::$phase,
        );
        let result = $operation;
        if let Some(observation) = observation {
            observation.finish(result.is_ok());
        }
        result
    }};
}

#[cfg(not(all(feature = "diagnostic-phases", target_os = "linux")))]
#[macro_export]
macro_rules! with_native_phase_export {
    ($operation:expr) => {
        $operation
    };
}

#[cfg(all(feature = "diagnostic-phases", target_os = "linux"))]
#[macro_export]
macro_rules! with_native_phase_export {
    ($operation:expr) => {{
        let diagnostics = $crate::native_phase_sink::start();
        let result = $operation;
        if let Some(diagnostics) = diagnostics {
            diagnostics.finished(result.is_ok());
        }
        result
    }};
}

#[cfg(all(feature = "diagnostic-phases", target_os = "linux"))]
mod enabled {
    use serde::Serialize;
    use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
    use std::sync::Mutex;
    use std::time::Instant;

    pub(crate) const MAX_OBSERVATIONS_PER_PHASE: u64 = 100_000;
    pub(crate) const MAX_DURATION_NS: u64 = 60_000_000_000;
    const PHASE_COUNT: usize = 7;

    static COLLECTOR: Collector = Collector::new();

    struct Collector {
        enabled: AtomicBool,
        loss_observed: AtomicBool,
        active: AtomicUsize,
        aggregates: Mutex<[Aggregate; PHASE_COUNT]>,
    }

    impl Collector {
        const fn new() -> Self {
            Self {
                enabled: AtomicBool::new(false),
                loss_observed: AtomicBool::new(false),
                active: AtomicUsize::new(0),
                aggregates: Mutex::new([Aggregate::EMPTY; PHASE_COUNT]),
            }
        }

        fn enable(&self) {
            self.enabled.store(true, Ordering::Relaxed);
        }

        fn begin(&self, phase: Phase) -> Option<Observation<'_>> {
            if !self.enabled.load(Ordering::Relaxed) {
                return None;
            }
            self.active.fetch_add(1, Ordering::Relaxed);
            Some(Observation {
                collector: self,
                phase,
                started: Some(Instant::now()),
            })
        }

        fn record(&self, phase: Phase, started: Instant, outcome: Outcome) {
            let elapsed_ns = started.elapsed().as_nanos();
            match self.aggregates.try_lock() {
                Ok(mut aggregates) => aggregates[phase as usize].record(elapsed_ns, outcome),
                Err(_) => self.loss_observed.store(true, Ordering::Relaxed),
            }
        }
    }

    #[derive(Clone, Copy)]
    pub(crate) enum Phase {
        ClientConnect,
        ClientAuthenticate,
        ClientRequestWriteFlush,
        ClientCommittedResponseRead,
        ResidentEvaluate,
        UnixSocketCreation,
        LoopbackConnectHandle,
    }

    impl Phase {
        const ALL: [Self; PHASE_COUNT] = [
            Self::ClientConnect,
            Self::ClientAuthenticate,
            Self::ClientRequestWriteFlush,
            Self::ClientCommittedResponseRead,
            Self::ResidentEvaluate,
            Self::UnixSocketCreation,
            Self::LoopbackConnectHandle,
        ];

        const fn name(self) -> &'static str {
            match self {
                Self::ClientConnect => "client_connect_inclusive",
                Self::ClientAuthenticate => "client_authenticate",
                Self::ClientRequestWriteFlush => "client_request_write_flush",
                Self::ClientCommittedResponseRead => "client_committed_response_read",
                Self::ResidentEvaluate => "resident_evaluate_inclusive",
                Self::UnixSocketCreation => "unix_socket_creation",
                Self::LoopbackConnectHandle => "loopback_connect_handle",
            }
        }
    }

    #[derive(Clone, Copy)]
    enum Outcome {
        ReturnedOk,
        ReturnedErr,
        Unwound,
        Abandoned,
    }

    #[derive(Clone, Copy, Serialize)]
    struct Aggregate {
        retained_count: u64,
        returned_ok: u64,
        returned_err: u64,
        unwound: u64,
        abandoned: u64,
        duration_ns_sum: u64,
        duration_ns_min: u64,
        duration_ns_max: u64,
        duration_clipped: bool,
        observations_discarded_at_cap: bool,
    }

    impl Aggregate {
        const EMPTY: Self = Self {
            retained_count: 0,
            returned_ok: 0,
            returned_err: 0,
            unwound: 0,
            abandoned: 0,
            duration_ns_sum: 0,
            duration_ns_min: 0,
            duration_ns_max: 0,
            duration_clipped: false,
            observations_discarded_at_cap: false,
        };

        fn record(&mut self, elapsed_ns: u128, outcome: Outcome) {
            if self.retained_count == MAX_OBSERVATIONS_PER_PHASE {
                self.observations_discarded_at_cap = true;
                return;
            }
            let duration = elapsed_ns.min(u128::from(MAX_DURATION_NS)) as u64;
            self.duration_clipped |= elapsed_ns > u128::from(MAX_DURATION_NS);
            self.duration_ns_min = if self.retained_count == 0 {
                duration
            } else {
                self.duration_ns_min.min(duration)
            };
            self.duration_ns_max = self.duration_ns_max.max(duration);
            // The fixed retention and duration caps bound this sum below u64::MAX.
            self.duration_ns_sum += duration;
            self.retained_count += 1;
            match outcome {
                Outcome::ReturnedOk => self.returned_ok += 1,
                Outcome::ReturnedErr => self.returned_err += 1,
                Outcome::Unwound => self.unwound += 1,
                Outcome::Abandoned => self.abandoned += 1,
            }
        }
    }

    pub(crate) struct Observation<'a> {
        collector: &'a Collector,
        phase: Phase,
        started: Option<Instant>,
    }

    impl Observation<'_> {
        pub(crate) fn finish(mut self, returned_ok: bool) {
            if let Some(started) = self.started.take() {
                let outcome = if returned_ok {
                    Outcome::ReturnedOk
                } else {
                    Outcome::ReturnedErr
                };
                self.collector.record(self.phase, started, outcome);
                self.collector.active.fetch_sub(1, Ordering::Relaxed);
            }
        }
    }

    impl Drop for Observation<'_> {
        fn drop(&mut self) {
            if let Some(started) = self.started.take() {
                // This records memory only; request threads never export.
                let outcome = if std::thread::panicking() {
                    Outcome::Unwound
                } else {
                    Outcome::Abandoned
                };
                self.collector.record(self.phase, started, outcome);
                self.collector.active.fetch_sub(1, Ordering::Relaxed);
            }
        }
    }

    pub(crate) fn begin(phase: Phase) -> Option<Observation<'static>> {
        COLLECTOR.begin(phase)
    }

    pub(crate) fn enable() {
        COLLECTOR.enable();
    }

    #[derive(Serialize)]
    struct PhaseReport {
        phase: &'static str,
        statistics: Option<Aggregate>,
    }

    #[derive(Serialize)]
    pub(crate) struct Report {
        schema: &'static str,
        scope: &'static str,
        span_semantics: &'static str,
        headline_timing_eligible: bool,
        complete_run: bool,
        snapshot_atomic: bool,
        collector_loss_observed: bool,
        active_observations_when_read: usize,
        max_observations_per_phase: u64,
        max_duration_ns: u64,
        unobserved_phase: &'static str,
        loopback_failed_internal_socket_creations: Option<u64>,
        all_platform_socket_opens: Option<u64>,
        phases: [PhaseReport; PHASE_COUNT],
    }

    fn snapshot_collector(collector: &Collector) -> Option<Report> {
        let aggregates = *collector.aggregates.try_lock().ok()?;
        Some(Report {
            schema: "hol-guard-native-phase-diagnostics.v1",
            scope: "diagnostic_instrumented_process_snapshot",
            span_semantics: "inclusive_do_not_sum",
            headline_timing_eligible: false,
            // Existing resident workers are not joined or drained by diagnostics.
            // A snapshot cannot prove that queued or later work is absent.
            complete_run: false,
            snapshot_atomic: false,
            collector_loss_observed: collector.loss_observed.load(Ordering::Relaxed),
            active_observations_when_read: collector.active.load(Ordering::Relaxed),
            max_observations_per_phase: MAX_OBSERVATIONS_PER_PHASE,
            max_duration_ns: MAX_DURATION_NS,
            unobserved_phase: "null_missing_or_unretained_not_zero_cost",
            loopback_failed_internal_socket_creations: None,
            all_platform_socket_opens: None,
            phases: Phase::ALL.map(|phase| {
                let aggregate = aggregates[phase as usize];
                PhaseReport {
                    phase: phase.name(),
                    statistics: (aggregate.retained_count != 0).then_some(aggregate),
                }
            }),
        })
    }

    pub(crate) fn snapshot() -> Option<Report> {
        snapshot_collector(&COLLECTOR)
    }

    #[cfg(test)]
    mod tests {
        use super::*;
        include!("native_phase_observation_tests.rs");
    }
}

#[cfg(all(feature = "diagnostic-phases", target_os = "linux"))]
pub(crate) use enabled::{begin, enable, snapshot, Phase, Report};

